contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint firstVal, uint secondVal) public {
        require(firstVal != secondVal);
        c.SetMinSum(firstVal); if (__ESBMC_reverted()) return;
        uint afterFirst = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetMinSum(secondVal); if (__ESBMC_reverted()) return;
        uint afterSecond = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(afterFirst == firstVal && afterSecond == secondVal);
    }
}

