pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 firstVal, uint256 secondVal) internal {
        vm.assume(firstVal != secondVal);
        try c.SetMinSum(firstVal) {} catch { return; }
        uint256 afterFirst;
        try c.MinSum() returns (uint256 __r) { afterFirst = __r; } catch { return; }
        try c.SetMinSum(secondVal) {} catch { return; }
        uint256 afterSecond;
        try c.MinSum() returns (uint256 __r) { afterSecond = __r; } catch { return; }
        assertTrue(afterFirst == firstVal && afterSecond == secondVal);
    }

    function testFuzz_run(uint256 firstVal, uint256 secondVal) public {
        _run(firstVal, secondVal);
    }

    receive() external payable {}
}
